@id("close-workorder-main-with-human-approval")
permit (principal, action == Drupe::Action::"close_workorder", resource)
when { context.input.site_id == "MAIN" }
when temporal {
  formerly within 1h Drupe::Action::"get_workorder"::response{
    eventResource: resource,
    input.wonum: context.input.wonum,
    input.site_id: context.input.site_id,
    output.approval_outcome: Drupe::get_workorder_Output_approval_outcome::"GRANTED",
    output.approver_type: Drupe::get_workorder_Output_approver_type::"HUMAN"
  }
  &&
  // a later lookup showing the approval was rejected revokes it
  !Drupe::Action::"get_workorder"::response{
    eventResource: resource,
    input.wonum: context.input.wonum,
    input.site_id: context.input.site_id,
    output.approval_outcome: Drupe::get_workorder_Output_approval_outcome::"REJECTED"
  } since within 1h Drupe::Action::"get_workorder"::response{
    eventResource: resource,
    input.wonum: context.input.wonum,
    input.site_id: context.input.site_id,
    output.approval_outcome: Drupe::get_workorder_Output_approval_outcome::"GRANTED",
    output.approver_type: Drupe::get_workorder_Output_approver_type::"HUMAN"
  }
  &&
  // a later lookup showing the approval is pending again revokes it
  !Drupe::Action::"get_workorder"::response{
    eventResource: resource,
    input.wonum: context.input.wonum,
    input.site_id: context.input.site_id,
    output.approval_outcome: Drupe::get_workorder_Output_approval_outcome::"PENDING"
  } since within 1h Drupe::Action::"get_workorder"::response{
    eventResource: resource,
    input.wonum: context.input.wonum,
    input.site_id: context.input.site_id,
    output.approval_outcome: Drupe::get_workorder_Output_approval_outcome::"GRANTED",
    output.approver_type: Drupe::get_workorder_Output_approver_type::"HUMAN"
  }
};

